SET search_path = big, public;
EXPLAIN (ANALYZE)
SELECT payment_id, merchant_id, amount_minor, created_at
FROM payments
WHERE card_id = 4242;

CREATE INDEX payments_card_idx ON payments (card_id);

EXPLAIN (ANALYZE)
SELECT payment_id, merchant_id, amount_minor, created_at
FROM payments
WHERE card_id = 4242;

SELECT level + 1 AS levels FROM bt_metap('payments_card_idx');
SELECT type, count(*) AS pages, round(avg(live_items)) AS avg_items
FROM bt_multi_page_stats('payments_card_idx', 1, -1) GROUP BY type ORDER BY type;
SELECT relname, relpages, pg_size_pretty(pg_relation_size(oid)) AS size
FROM pg_class
WHERE relname IN ('payments', 'payments_card_idx') AND relnamespace = 'big'::regnamespace;

SET search_path = big, public;
CREATE INDEX payments_created_merchant_idx ON payments (created_at, merchant_id);
EXPLAIN (ANALYZE, COSTS OFF)
SELECT payment_id, amount_minor, created_at
FROM payments
WHERE merchant_id = 1000 AND created_at >= '2026-09-01' AND created_at < '2026-10-01'
ORDER BY created_at DESC
LIMIT 20;
DROP INDEX payments_created_merchant_idx;

CREATE INDEX payments_merchant_created_idx ON payments (merchant_id, created_at)
    INCLUDE (status, amount_minor);
EXPLAIN (ANALYZE, COSTS OFF)
SELECT payment_id, amount_minor, created_at
FROM payments
WHERE merchant_id = 1000 AND created_at >= '2026-09-01' AND created_at < '2026-10-01'
ORDER BY created_at DESC
LIMIT 20;
EXPLAIN (ANALYZE, COSTS OFF)
SELECT count(*), sum(amount_minor)
FROM payments
WHERE merchant_id = 1000 AND status = 'succeeded'
  AND created_at >= '2026-09-01' AND created_at < '2026-10-01';
DROP INDEX payments_merchant_created_idx;

CREATE INDEX payments_status_created_idx ON payments (status, created_at);
EXPLAIN (ANALYZE, COSTS OFF)
SELECT payment_id, merchant_id, amount_minor
FROM payments
WHERE created_at >= '2026-09-01 12:00' AND created_at < '2026-09-01 12:05';
DROP INDEX payments_status_created_idx;

SET search_path = big, public;
CREATE EXTENSION IF NOT EXISTS pg_visibility;
CREATE TABLE pay_copy (LIKE payments) WITH (autovacuum_enabled = off);
SELECT count(*) FROM payments WHERE payment_id <= 200000;   -- warm the source pages

SELECT pg_current_wal_lsn() AS before \gset
INSERT INTO pay_copy SELECT * FROM payments WHERE payment_id <= 200000;
SELECT pg_size_pretty(pg_wal_lsn_diff(pg_current_wal_lsn(), :'before')) AS wal_no_index;

TRUNCATE pay_copy;
ALTER TABLE pay_copy ADD PRIMARY KEY (payment_id);
CREATE INDEX ON pay_copy (card_id);
CREATE INDEX pay_copy_merchant_idx ON pay_copy (merchant_id, created_at) INCLUDE (amount_minor);
SELECT pg_current_wal_lsn() AS before \gset
INSERT INTO pay_copy SELECT * FROM payments WHERE payment_id <= 200000;
SELECT pg_size_pretty(pg_wal_lsn_diff(pg_current_wal_lsn(), :'before')) AS wal_three_indexes;
ANALYZE pay_copy;

SELECT all_visible, pg_relation_size('pay_copy') / 8192 AS pages FROM pg_visibility_map_summary('pay_copy');
EXPLAIN (ANALYZE, COSTS OFF)
SELECT count(*), sum(amount_minor) FROM pay_copy WHERE merchant_id = 1000;

VACUUM pay_copy;
SELECT all_visible, pg_relation_size('pay_copy') / 8192 AS pages FROM pg_visibility_map_summary('pay_copy');
EXPLAIN (ANALYZE, COSTS OFF)
SELECT count(*), sum(amount_minor) FROM pay_copy WHERE merchant_id = 1000;

UPDATE pay_copy SET status = 'failed'
WHERE payment_id = (SELECT min(payment_id) FROM pay_copy WHERE merchant_id = 1000);
EXPLAIN (ANALYZE, COSTS OFF)
SELECT count(*), sum(amount_minor) FROM pay_copy WHERE merchant_id = 1000;
DROP TABLE pay_copy;

