SELECT count(*) FROM payments WHERE created_at >= '2026-09-01' AND created_at < '2026-09-02';
CREATE INDEX payments_day_idx ON payments ((created_at::date));

PREPARE by_id(numeric) AS SELECT payment_id, amount_minor FROM payments WHERE payment_id = $1;
EXPLAIN (ANALYZE, COSTS OFF) EXECUTE by_id(500000);
