EXPLAIN (COSTS OFF) SELECT sum(amount_minor) FROM payments WHERE status = 'succeeded';
EXPLAIN (COSTS OFF) SELECT sum(amount_minor) FROM payments WHERE status = 'pending';
CREATE INDEX payments_pending_idx ON payments (created_at) WHERE status = 'pending';
SELECT pg_size_pretty(pg_relation_size('payments_created_idx')) AS every_payment,
       pg_size_pretty(pg_relation_size('payments_status_idx')) AS status_idx,
       pg_size_pretty(pg_relation_size('payments_pending_idx')) AS pending_only;
DROP INDEX payments_created_idx, payments_status_idx, payments_pending_idx, customers_lower_email_idx;

