-- (1) equality, then the sort column: Index Scan Backward, no Sort, stops after 10
CREATE INDEX ON payments (card_id, created_at);

-- (2) index the expression the query uses: Index Scan (or Bitmap) with Index Cond on lower(email)
CREATE INDEX ON customers (lower(email));

-- (3) a partial index holds only the 1% that is ever queried: small, and an Index Scan
CREATE INDEX ON payments (created_at) WHERE status = 'pending';

-- (4) key for the search, INCLUDE for the sum: Index Only Scan, Heap Fetches near 0 after VACUUM
CREATE INDEX ON payments (merchant_id, created_at) INCLUDE (amount_minor);

